"use strict";
eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   driveTechArticles: () => (/* binding */ driveTechArticles)\n/* harmony export */ });\nconst driveTechArticles = [\n    {\n        id: 3,\n        slug: \"autonomous-mobility-ai\",\n        category: \"DRIVE & TECH\",\n        categorySlug: \"drive-tech\",\n        title: \"Autonomous Mobility & AI\",\n        titleKo: \"자율주행과 AI 혁명: 모빌리티의 현재와 미래\",\n        excerpt: \"자율주행 기술과 AI 자동화가 바꾸는 이동의 패러다임. 2026년 현재 어디까지 왔는가.\",\n        date: \"2026.03.09\",\n        readTime: \"7 MIN\",\n        image: \"https://images.unsplash.com/photo-1492144534655-ae79c964c9d7?w=800&q=80\",\n        heroImage: \"https://images.unsplash.com/photo-1492144534655-ae79c964c9d7?w=800&q=80\",\n        featured: true,\n        tags: [\n            \"자율주행\",\n            \"AI\",\n            \"모빌리티\"\n        ],\n        author: \"PAGEONEWORKS\",\n        body: \"2026년, 자율주행 기술은 상용화의 문턱을 넘어섰습니다.\\n\\n테슬라의 FSD와 웨이모의 로보택시가 주요 도시에서 운영되고 있습니다.\\n\\nAI의 발전은 전체 모빌리티 생태계를 재편하고 있습니다.\"\n    },\n    {\n        id: 7,\n        slug: \"carnguy-import-car-repair-guide\",\n        category: \"DRIVE & TECH\",\n        categorySlug: \"drive-tech\",\n        title: \"Car&Guy: Import Car Repair Specialist\",\n        titleKo: \"경기도 광주 수입차 사고수리 — 카앤가이 전문 가이드\",\n        excerpt: \"벤츠\\xb7BMW\\xb7포르쉐 사고, 어디서 고쳐야 할까. 경기도 광주 1급 자동차공업사 카앤가이의 서비스와 수리 노하우를 정리했습니다.\",\n        date: \"2026.03.17\",\n        readTime: \"12 MIN\",\n        image: \"https://images.unsplash.com/photo-1503376780353-7e6692767b70?w=1200&q=85\",\n        heroImage: \"https://images.unsplash.com/photo-1503376780353-7e6692767b70?w=1200&q=85\",\n        featured: true,\n        tags: [\n            \"수입차수리\",\n            \"경기도광주\",\n            \"판금도색\",\n            \"BMW수리\",\n            \"벤츠수리\",\n            \"사고수리\",\n            \"보험처리\"\n        ],\n        author: \"PAGEONEWORKS\",\n        isSponsored: true,\n        sponsorName: \"카앤가이 CAR&GUY\",\n        sponsorUrl: \"tel:027395415\",\n        body: `수입차를 타다 보면 누구나 한 번쯤 마주하는 순간이 있습니다. 주차장에서 발견한 긁힘, 갑작스러운 접촉사고, 빗길에서의 미끄러짐. 문제는 그 다음입니다. 어디서 고쳐야 하나.\r\n\r\n일반 공업사에 맡겼다가 이색현상이 생겨 낭패를 본 경험, 딜러십 서비스센터에 맡겼더니 수리비가 예상보다 훨씬 나와 당황한 경험. 수입차 오너라면 한 번쯤 겪어봤을 이야기입니다.\r\n\r\n##IMAGE##https://images.unsplash.com/photo-1618843479313-40f8afb4b4d8?w=1200&q=85##CAPTION##경기도 광주 1급 자동차공업사 카앤가이##END##\r\n\r\n■ 카앤가이, 어떤 곳인가\r\n\r\n카앤가이는 경기도 광주시에 위치한 국토교통부 인증 1급 자동차공업사입니다. 업력 15년, 누적 수리 3,200건 이상. 메르세데스-벤츠, BMW, 아우디, 포르쉐, 테슬라, 렉서스, 재규어, 페라리, 람보르기니, 마세라티, 랜드로버, 폭스바겐 등 12개 수입 브랜드를 전문으로 다룹니다.\r\n\r\n1급 자동차공업사 자격은 국토교통부에서 정한 설비 기준과 기술 인력 요건을 충족해야 취득할 수 있습니다. 독일제 분광측색계와 조색기를 보유해 30만 가지 이상의 색상 데이터를 기반으로 조색 작업을 진행합니다.\r\n\r\n##IMAGE##https://images.unsplash.com/photo-1486262715619-67b85e0b08d3?w=1200&q=85##CAPTION##수입차 전용 장비 보유##END##\r\n\r\n■ 수입차 수리, 왜 전문점이어야 하는가\r\n\r\n수입차와 국산차의 수리는 구조적으로 다릅니다. 차체 소재, 도장 방식, 사용하는 도료까지 모두 다릅니다. 벤츠의 경우 차체 일부에 고강도 스틸과 알루미늄을 혼합 사용합니다. 일반 방식으로 용접하면 차체 강성이 저하됩니다. 수입차는 5~7겹의 베이스코트와 클리어코트가 정밀하게 적용됩니다.\r\n\r\n##IMAGE##https://images.unsplash.com/photo-1503376780353-7e6692767b70?w=1200&q=85##CAPTION##독일제 조색기로 이색현상 없는 색상 매칭##END##\r\n\r\n■ 핵심 서비스\r\n\r\n【보험 수리】\r\n\r\n자차보험처리부터 대물미수선처리, 음주운전 면책금 상담, 격락손해소송 지원까지 보험 관련 전 과정을 원스탑으로 대행합니다. 보험접수 성공률 100%.\r\n\r\n【판금 & 도색】\r\n\r\n독일제 분광측색계로 차량의 VIN 번호와 도장 코드를 기반으로 정확한 색상을 배합합니다. 이색현상 없는 완벽한 복원이 가능합니다.\r\n\r\n【휠 & 타이어 복원】\r\n\r\n17~21인치 전 규격 알루미늄 합금 휠 복원이 가능합니다. 도장, 연마, 성형까지 원스탑으로 처리합니다.\r\n\r\n【PPF & 유리막 코팅】\r\n\r\n수입차 전용 PPF 보호 필름으로 스크래치, 돌 튐으로부터 도장면을 보호합니다.\r\n\r\n【픽업 & 딜리버리】\r\n\r\n경기 전 지역 무상 픽업 서비스를 운영합니다. 24시간 긴급 사고 접수가 가능합니다.\r\n\r\n##IMAGE##https://images.unsplash.com/photo-1449965408869-eaa3f722e40d?w=1200&q=85##CAPTION##24시간 긴급 픽업 서비스##END##\r\n\r\n■ 실제 수리 사례 — 벤츠 E300 후방 추돌 복원\r\n\r\n2025년 11월, 판교에서 후방 추돌 사고를 당한 벤츠 E300 사례입니다. 신호 대기 중 후방 추돌로 트렁크 리드와 리어 범퍼 전체가 손상됐습니다. 외관 손상 외에 리어 크로스멤버 미세 변형이 확인됐고, 보험사 초기 견적을 재협상해 차체 교정 비용까지 보험 적용을 받았습니다. Car-O-Liner 차체 교정 후 리어 범퍼 교체, 트렁크 리드 판금 및 도색, 전체 조립 점검까지 수리 기간 6일, 무상 대차 이용으로 출고 당시 수준으로 복원 완료했습니다.\r\n\r\n■ 수입차 사고 후 단계별 대응\r\n\r\n1단계 — 현장 기록: 차량 손상 부위, 상대 차량, 사고 현장을 다양한 각도에서 촬영합니다.\r\n\r\n2단계 — 보험사 신고: 현장 기록 후 바로 보험사에 신고합니다. 카앤가이에 연락하면 보험 처리 전 과정을 대행합니다.\r\n\r\n3단계 — 전문 업체 선택: 소비자는 수리 업체를 직접 선택할 권리가 있습니다. 딜러십 서비스센터가 아닌 전문 공업사를 선택할 수 있습니다.\r\n\r\n4단계 — 수리 확인: 수리 완료 후 색상 매칭, 패널 정렬, 도장 품질을 직접 확인합니다.\r\n\r\nQ. 서울에서도 이용할 수 있나요?\r\nA. 서울 강남·서초·용산·판교·분당 등 경기권 전 지역 무상 픽업이 가능합니다. 픽업부터 출고까지 차량을 직접 가져오실 필요가 없습니다. 카앤가이에서 고객 차량을 직접 수거하고, 수리 완료 후 지정 장소로 다시 배달해 드립니다. 주차 걱정 없이 편리하게 이용하실 수 있습니다.\r\n\r\nQ. 수리 기간은 얼마나 걸리나요?\r\nA. 단순 도색은 2~3일, 판금 포함 수리는 5~7일, 대형 사고는 2~3주 정도 소요됩니다. 수리 기간 중에는 무상 대차 서비스를 제공해 드립니다. 정밀 진단 후 예상 수리 기간을 먼저 안내해 드리며, 진행 중 카카오톡으로 실시간 업데이트를 드립니다. 일정이 변경될 경우 즉시 연락드립니다.\r\n\r\nQ. 딜러십 서비스센터와 비교하면 어떤가요?\r\nA. 장비 수준은 정식 서비스센터와 동일하게 갖추고 있습니다. 비용은 딜러십 대비 20~40% 낮은 경우가 많습니다. 보험 수리의 경우 보험사와 직접 협상해 수리 범위를 최대한 확보합니다. 고객이 체감하는 자기부담금이 낮아지는 경우가 많습니다.\r\n\r\nQ. 자기부담금이 걱정됩니다.\r\nA. 자기부담금 지원 프로그램을 운영 중입니다. 무상 견적 단계에서 예상 자기부담금을 먼저 안내해 드립니다. 보험사와의 협상을 통해 자기부담금을 최소화할 수 있도록 최선을 다합니다. 추가 비용 없이 상담을 먼저 받아보시길 권장합니다.\r\n\r\nQ. 페라리, 람보르기니도 수리 가능한가요?\r\nA. 가능합니다. 카본파이버 소재 수리 기술을 보유하고 있습니다. 페라리, 람보르기니, 맥라렌, 벤틀리 등 하이엔드 브랜드 수리 실적을 보유하고 있습니다. 전문 기술 인력이 브랜드별 매뉴얼에 따라 작업을 진행합니다.\r\n\r\nQ. 품질 보증이 있나요?\r\nA. 모든 수리에 3개월 품질 보증을 제공합니다. 도색 후 이색현상이나 도장 불량이 발생할 경우 무상으로 재시공해 드립니다. 보증 기간 내 발생한 문제는 100% 책임집니다. 고객 만족 시까지 재작업을 반복합니다.\r\n\r\nQ. 야간이나 주말 사고는요?\r\nA. 24시간 긴급 접수가 가능합니다. 야간·주말·공휴일 언제든지 전화 또는 카카오톡으로 접수를 받습니다. 긴급 상황 시 현장 출동 또는 긴급 픽업 서비스를 지원합니다. 사고 직후 당황스러운 상황에서도 처리 절차를 단계별로 안내해 드립니다.\r\n\r\nQ. 음주운전 사고도 처리 가능한가요?\r\nA. 음주운전 면책금 상담도 진행합니다. 음주운전 사고의 경우 보험 처리가 복잡해지는 경우가 많습니다. 면책금 범위, 보험 처리 가능 여부, 자비 수리 예상 비용까지 무료로 상담해 드립니다. 해당 케이스 처리 경험이 풍부하니 부담 없이 연락 주세요.\r\n\r\n##IMAGE##https://images.unsplash.com/photo-1486262715619-67b85e0b08d3?w=1200&q=85##CAPTION##카앤가이 작업 현장##END##\r\n\r\n■ 오시는 길\r\n\r\n경기도 광주시 광남안로 12 카앤가이. 운영: 평일 09:00–18:00 / 야간·주말 24시간 긴급 접수.`\n    },\n    {\n        id: 8,\n        slug: \"pageoneworks-webinar-platform\",\n        category: \"DRIVE & TECH\",\n        categorySlug: \"drive-tech\",\n        title: \"Webinar Platform & Live Streaming by PAGEONEWORKS\",\n        titleKo: \"웨비나 플랫폼의 모든 것: 온라인 컨퍼런스\\xb7라이브 스트리밍 커스터마이징 전문기업 페이지원웍스\",\n        excerpt: \"삼성전자\\xb7롯데\\xb7SK쉴더스\\xb7한양대병원이 선택한 온라인 컨퍼런스 전문기업. 기획부터 중계\\xb7브랜드 디자인까지 원스톱으로 제공하는 웨비나 플랫폼 라이브팩을 소개합니다.\",\n        date: \"2026.03.27\",\n        readTime: \"12 MIN\",\n        image: \"https://images.unsplash.com/photo-1591115765373-5207764f72e7?w=1200&q=85\",\n        heroImage: \"https://images.unsplash.com/photo-1591115765373-5207764f72e7?w=1600&q=85\",\n        featured: true,\n        tags: [\n            \"웨비나\",\n            \"라이브스트리밍\",\n            \"온라인컨퍼런스\",\n            \"페이지원웍스\",\n            \"커스터마이징플랫폼\"\n        ],\n        author: \"PAGEONEWORKS 편집부\",\n        isSponsored: true,\n        sponsorName: \"페이지원웍스\",\n        sponsorUrl: \"https://pageone.works\",\n        body: `기업의 중요한 발표를 준비하면서 한 번쯤 이런 고민을 해본 적 있을 겁니다. 유튜브 라이브로 진행하자니 브랜드 이미지가 살지 않고, 줌으로 하자니 수백 명의 참석자를 감당하기 어렵습니다. 전문 중계 업체를 쓰자니 비용과 품질이 걱정됩니다. 온라인 행사의 시대, 이제는 플랫폼 자체가 브랜드입니다.\r\n\r\n삼성전자, 롯데, SK쉴더스, 한양대학교병원, 연세대학교 의과대학. 이 기업들의 공통점은 모두 페이지원웍스와 함께 온라인 컨퍼런스를 진행했다는 것입니다. 15년의 운영 노하우와 자체 플랫폼 라이브팩을 바탕으로, 기획부터 중계·브랜드 디자인까지 원스톱으로 제공하는 국내 유일의 온라인 행사 종합 솔루션입니다.\r\n\r\n##IMAGE##https://images.unsplash.com/photo-1591115765373-5207764f72e7?w=1200&q=85##CAPTION##전문 중계팀이 구성하는 방송급 온라인 컨퍼런스 현장##END##\r\n\r\n■ 웨비나란 무엇인가\r\n\r\n웨비나(Webinar)는 Web과 Seminar의 합성어입니다. 물리적 공간에 모이지 않고도 수백, 수천 명이 동시에 참여할 수 있는 온라인 세미나·컨퍼런스를 의미합니다. 코로나 이후 비대면 문화가 정착되면서 기업의 신제품 발표회, 투자자 IR, 의학 학술 심포지움, 대학 입학설명회까지 그 활용 범위가 폭발적으로 확장됐습니다.\r\n\r\n그러나 단순히 화상회의 링크를 보내는 것이 웨비나의 전부가 아닙니다. 브랜드 아이덴티티가 적용된 전용 플랫폼, 전문 방송 장비를 통한 고화질 중계, 실시간 Q&A와 투표 기능, 행사 후 VOD 아카이빙까지. 진정한 웨비나는 오프라인 행사 이상의 경험을 온라인으로 구현하는 것입니다.\r\n\r\n##IMAGE##https://images.unsplash.com/photo-1552581234-26160f608093?w=1200&q=85##CAPTION##수백 명이 동시 접속하는 커스터마이징 웨비나 플랫폼 화면##END##\r\n\r\n■ 라이브 스트리밍, 왜 전문성이 중요한가\r\n\r\n라이브 스트리밍은 실시간으로 영상을 송출하는 기술입니다. 개인 방송과 기업 행사의 차이는 안정성과 화질, 그리고 브랜드 경험에 있습니다. 페이지원웍스는 Naver Cloud, Amazon Web Service, Google Cloud Computing 세 가지 클라우드 인프라를 기반으로 대용량 트래픽에도 끊김 없는 FULL HD·4K 스트리밍을 제공합니다.\r\n\r\n두 개 이상의 멀티 채널로 동시 송출하여 기술적 사고를 최소화합니다. 스포츠 중계, 세미나, 외주 방송 경험이 풍부한 PD와 촬영감독, 그래픽 담당, 편집자로 이루어진 전문 중계팀이 TV 중계와 동일 수준의 방송 품질을 구현합니다.\r\n\r\n##IMAGE##https://images.unsplash.com/photo-1478737270239-2f02b77fc618?w=1200&q=85##CAPTION##TV 중계급 장비로 구성하는 기업 라이브 스트리밍 세팅##END##\r\n\r\n■ 커스터마이징 플랫폼이 만드는 차이\r\n\r\n유튜브 라이브나 줌은 훌륭한 도구지만, 기업 행사에는 한계가 있습니다. 플랫폼에 기업 로고나 브랜드 컬러를 적용할 수 없고, 참석자 관리·데이터 수집·보안 설정에 제약이 따릅니다. 페이지원웍스의 라이브팩은 기업별로 완전히 커스터마이징된 전용 플랫폼을 구축합니다.\r\n\r\n로딩 화면부터 대기 화면, 진행 화면, 자막 하단 바, 참석자 이름 표시까지 모든 화면 요소에 기업 브랜드가 반영됩니다. 참석자 사전 등록·인증, 실시간 Q&A, 투표, 출석 확인, 행사 후 데이터 리포트까지 제공합니다.\r\n\r\n##IMAGE##https://images.unsplash.com/photo-1558403194-611308249627?w=1200&q=85##CAPTION##기업 브랜드가 완전히 적용된 전용 웨비나 플랫폼##END##\r\n\r\n■ 핵심 서비스\r\n\r\n【온라인 컨퍼런스 컨설팅】\r\n\r\n행사 기획 단계부터 진행·마무리까지 전담 컨설턴트가 함께합니다. 처음 온라인 행사를 준비하는 기업도 일정에 맞춰 안정적으로 진행할 수 있도록 전 과정을 책임집니다.\r\n\r\n【라이브 스트리밍 중계】\r\n\r\n방송 PD, 촬영감독, 그래픽 담당, 편집자로 구성된 전문 중계팀이 FULL HD·4K 품질로 송출합니다. 멀티 채널 동시 송출로 기술적 사고를 최소화합니다.\r\n\r\n【브랜드 디자인】\r\n\r\n네이버·카카오 출신 브랜드 디자이너가 컨퍼런스 브랜딩, 그래픽, 인쇄·출판까지 통일된 브랜드 경험을 설계합니다. 행사 포스터, 이메일 초청장, SNS 홍보 콘텐츠까지 원스톱으로 제작합니다.\r\n\r\n【마케팅 · 광고】\r\n\r\n온·오프라인 광고 집행과 바이럴 마케팅으로 행사 참석률을 극대화합니다. 정확한 고객 분석과 영향력 있는 광고 채널 전략을 수립합니다.\r\n\r\n##IMAGE##https://images.unsplash.com/photo-1560472354-b33ff0c44a43?w=1200&q=85##CAPTION##삼성전자·롯데·SK쉴더스·한양대병원 등 500+ 프로젝트 완료##END##\r\n\r\n■ 페이지원웍스를 선택해야 하는 이유\r\n\r\n15년간 대기업·지자체·대학병원·대학교 등 다양한 기관의 온·오프라인 행사를 진행하며 쌓은 노하우가 있습니다. 삼성전자 Neo QLED 테크 세미나는 전 세계 기자를 대상으로 한 글로벌 행사였습니다. 롯데 CES 디브리핑, SK쉴더스 비전 선포식, 한양대 줄기세포 연구회 국제 심포지움까지 규모와 업종을 가리지 않고 최고의 결과를 만들어왔습니다.\r\n\r\n■ 자주 묻는 질문\r\n\r\nQ. 웨비나 플랫폼 구축에 얼마나 걸리나요?\r\nA. 행사 규모와 커스터마이징 요구 사항에 따라 통상 2~4주 소요됩니다. 기본 플랫폼은 1주일 내 구축이 가능하며, 브랜드 디자인 적용과 기능 커스터마이징은 추가 시간이 필요합니다. 긴급 행사의 경우 빠른 대응이 가능하니 일정을 먼저 공유해 주시면 최대한 맞춰드립니다. 행사 최소 3주 전에 상담을 시작하시는 것을 권장합니다.\r\n\r\nQ. 동시 접속자가 수천 명이어도 끊김이 없나요?\r\nA. Naver Cloud, AWS, Google Cloud 세 가지 인프라를 혼합 운용하여 대용량 트래픽에 안정적으로 대응합니다. 멀티 채널 동시 송출 방식을 적용해 한 채널에 문제가 생겨도 즉시 다른 채널로 전환됩니다. 삼성전자, 롯데 등 대규모 행사에서도 무중단 서비스를 제공한 실적이 있습니다. 행사 전 반드시 사전 리허설을 진행해 안정성을 최종 확인합니다.\r\n\r\nQ. 유튜브·줌과 어떤 점이 다른가요?\r\nA. 유튜브·줌은 범용 플랫폼이라 기업 브랜드를 완전히 적용하기 어렵습니다. 페이지원웍스는 기업 전용 URL과 브랜드 디자인이 적용된 플랫폼을 구축합니다. 참석자 사전 등록·인증, 실시간 Q&A, 투표, 출석 확인, 행사 후 데이터 리포트까지 제공합니다. 보안 측면에서도 비공개 행사에 최적화된 접근 권한 관리가 가능합니다.\r\n\r\nQ. 해외 참석자도 접속 가능한가요?\r\nA. 글로벌 CDN을 통해 해외 어느 지역에서도 안정적인 접속이 가능합니다. 영문 인터페이스 지원도 가능하며, 동시통역 기능 연동도 협의할 수 있습니다. 삼성전자 Neo QLED 테크 세미나는 전 세계 기자를 대상으로 진행된 글로벌 행사였습니다. 해외 접속 최적화를 위한 별도 서버 구성도 요청 시 가능합니다.\r\n\r\nQ. 행사 후 영상 다시보기 서비스가 가능한가요?\r\nA. 라이브 종료 후 VOD 서비스를 통해 다시보기를 제공합니다. 영상 편집, 자막 삽입, 챕터 분리 서비스도 별도 요청이 가능합니다. VOD 보관 기간은 고객사와 협의하여 결정하며, 보안이 필요한 경우 비공개 링크로 제공합니다. 참석하지 못한 임직원이나 관계자도 이후 편리하게 시청할 수 있습니다.\r\n\r\nQ. 브랜드 디자인은 어느 수준까지 커스터마이징되나요?\r\nA. 네이버·카카오 출신 브랜드 디자이너가 직접 담당합니다. 로딩 화면, 대기 화면, 진행 화면, 자막 하단 바, 참석자 이름 표시 등 모든 화면 요소에 기업 브랜드 컬러와 로고를 적용합니다. 행사 포스터, 이메일 초청장, SNS 홍보 콘텐츠까지 통일된 브랜드 경험으로 제작합니다. 오프라인 현수막, 무대 디자인 연계도 가능합니다.\r\n\r\nQ. 소규모 행사도 진행 가능한가요?\r\nA. 참석자 50명 이하의 소규모 웨비나부터 수천 명 규모의 대형 컨퍼런스까지 모두 대응합니다. 규모에 맞는 합리적인 패키지를 제안해 드리며, 소규모라도 전문 장비와 중계팀이 투입됩니다. 예산과 규모를 먼저 말씀해 주시면 최적화된 플랜을 무료로 제안해 드립니다.\r\n\r\nQ. 촬영 장비와 현장 인력은 직접 제공되나요?\r\nA. 방송 PD, 촬영감독, 그래픽 담당, 편집자 등 전문 중계팀이 직접 현장에 투입됩니다. 스포츠 중계, 세미나, 외주 방송 경험이 풍부한 팀으로 구성되어 있습니다. 고객사 장소에 직접 방문하여 세팅하며, 리허설부터 본 행사, 철수까지 전 과정을 책임집니다.\r\n\r\nQ. 의료·학술 분야 행사 경험이 있나요?\r\nA. 한양대학교병원, 연세대학교 의과대학, 원주세브란스기독병원, 충남대학교병원 등 다수의 의료·학술 행사를 진행했습니다. 학술 심포지움 특성상 요구되는 발표 자료 처리와 Q&A 운영, 참석자 인증에 풍부한 노하우를 보유하고 있습니다. CME 학점 인정 행사 운영 경험도 있어 학술 행사에 특화된 서비스를 제공합니다.\r\n\r\nQ. 견적은 어떻게 받을 수 있나요?\r\nA. 전화(02-739-5415) 또는 이메일(help@pageone.works)로 행사 일정, 규모, 요구 사항을 간단히 알려주시면 무료로 견적을 제안해 드립니다. 방문 상담도 가능하며, 비슷한 규모의 레퍼런스와 함께 상세 제안서를 보내드립니다. 예산이 정해진 경우 그 범위 내에서 최적의 플랜을 구성해 드립니다.\r\n\r\n##IMAGE##https://images.unsplash.com/photo-1497366216548-37526070297c?w=1200&q=85##CAPTION##서울 종로구 옥인3길 15 페이지원웍스 본사##END##\r\n\r\n■ 문의 및 상담\r\n\r\n전화:(02)739-5415\r\n이메일: help@pageone.works\r\n주소: 서울특별시 종로구 옥인3길 15, 1층 (주)페이지원웍스\r\n운영시간: 평일 09:00 – 18:00`\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./lib/articles/drive-tech.ts\n");

